using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Measurement.Pgm;
internal sealed class EquiprobablePgmSymmetricDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Measurement/Pgm/EquiprobablePgmSymmetric.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Complete symmetric qubit discrimination", H("Complete symmetric qubit discrimination"), Blocks(
            Node("dual_score", "Shared dual score", DescribeRole.Theorem, "For arbitrary matrices rho,E,Gamma, POVM completeness alone gives success=Re tr Gamma-sum_i Re tr[(Gamma-rho_i/N)E_i]. It is a shared algebra helper consumed by the dual bound and complementary-product proofs.", "mazhang2026pgmratio"),
            Node("dual_bound", "Shared dual bound", DescribeRole.Theorem, "For every actual finitePOVM and every dual matrix whose slacks Gamma-rho_i/N are positive semidefinite, actual success<=Re tr Gamma. This shared helper is consumed by the symmetric optimizer classification and the commuting interval proof.", "mazhang2026pgmratio"),
            Node("complementary_products", "Shared complementary products", DescribeRole.Theorem, "For any actual finitePOVM attaining a feasible dual trace, every actual dual slack has zero product with its corresponding effect. The proof reuses the existing PSD zero-trace-product theorem and is consumed by both the symmetric uniqueness and commuting every-optimum proofs.", "mazhang2026pgmratio"),
            Node("rho", "The actual symmetric ensemble", DescribeRole.Definition, "For real a,b,c the three matrices, in plus, minus, third order, are rho_+/-=[[a,+/-b],[+/-b,1-a]] and rho_3=diag(c,1-c). The existing success and pgmScore definitions retain equal original priors 1/3.", "mazhang2026pgmratio"),
            Node("pairPovm", "The actual two-projector measurement", DescribeRole.Definition, "The effects are Q_+=(I+X)/2, Q_-=(I-X)/2, and zero, where X=[[0,1],[1,0]]. These are positive semidefinite rank-one projectors summing to the identity; active means nonzero effect.", "mazhang2026pgmratio"),
            Node("pairGamma", "The two-active dual certificate", DescribeRole.Definition, "Gamma=diag(a+b,1-a+b)/3. Its pair slacks are (b/3)(I-X) and (b/3)(I+X), and its third slack is diag(b-(c-a),b+(c-a))/3. Positivity therefore includes both signs of c-a and the equality boundaries.", "mazhang2026pgmratio"),
            Node("states_posSemidef", "The earlier domain allows a singular pair", DescribeRole.Theorem, "For 0<a, 0<c<1 and b^2<=a(1-a), all three actual matrices are PSD and trace one. This certificate includes the singular equality boundary. Together with pair_classification and symmetric_scores, it retains the earlier strict-inactivity domain |c-a|<b, b>0, without extending the strict-PD three-active claim to a PSD boundary. It reuses the existing real two-by-two trace/determinant criterion and is consumed by states_posDef.", "anonymous2026pgmmechanism"),
            Node("states_posDef", "Strictly positive actual density matrices", DescribeRole.Theorem, "For every real a,b,c with a>0, 0<c<1, and a(1-a)-b^2>0, all three actual matrices are positive definite and have trace one. In particular the scientific strict domain 0<a,c<1 and 0<b<sqrt(a(1-a)) is included; the determinant form does not impose a spectral floor.", "mazhang2026pgmratio"),
            Node("pair_classification", "Uniqueness throughout the closed two-active region", DescribeRole.Theorem, "For every real a,b,c with b>0 and |c-a|<=b, pairPovm is an actual finitePOVM, scores (1+2b)/3, and every actual finitePOVM E is optimal among all actual finitePOVMs if and only if E=pairPovm. The optimization statement is stronger than the density-domain restriction: it needs only b>0 and the displayed absolute-value bound, while states_posDef supplies the physical strict-density domain. The certificate inequality applies to every complex Hermitian-positive effect family, not only real or diagonal competitors. Complementary slackness uses the existing zero_trace_mul_eq_zero supplier. The first two effects lie on the two orthogonal X rays. Completeness equates the third effect's diagonal entries; the sum of its two slack equations forces both to zero because b>0. Positivity then forces that whole effect to zero, including its off-diagonals. Completeness fixes both remaining weights to one. Thus delta=+b and delta=-b retain the same unique pair optimum; a singular third dual slack does not produce an extra optimal effect.", "mazhang2026pgmratio"),
            Node("upperPovm", "The actual upper three-active effects", DescribeRole.Definition, "For t=b/(c-a), the effects are E_+=outer(t,1)/2, E_-=outer(-t,1)/2 and E_3=diag(1-t^2,0). Here outer(v)=v v†. In the strict upper region 0<b<c-a, one has 0<t<1. The effects are positive, sum to I and are all nonzero. This is the positive-sign form of the verification note's Bloch formula; the opposite sign is handled by actual basis permutation in the classification owner.", "mazhang2026pgmratio"),
            Node("upperGamma", "The upper three-active dual certificate", DescribeRole.Definition, "Gamma=diag(c,1-a+b t)/3. Under (c-a)t=b its first slacks are ((c-a)/3) outer(1,-t) and ((c-a)/3) outer(1,t), and its third slack is diag(0,(c-a+b t)/3). These are actual positive matrices and their complementary products with the displayed effects vanish.", "mazhang2026pgmratio"),
            Node("upper_classification", "Unique optimum in the strict upper three-active region", DescribeRole.Theorem, "For every real a,b,c with 0<b<c-a, set t=b/(c-a). The displayed upperPovm is a finitePOVM with score (1+c-a+b t)/3, and an arbitrary actual complex finitePOVM E is optimal if and only if it equals upperPovm. On the strict density domain certified by states_posDef, this is P_opt=(1+R)/3 with R=((c-a)^2+b^2)/(c-a). Complementary slackness puts the first effects on the two tilted rays and the third on the first basis ray; completeness fixes both first weights to 1/2 and the remaining weight to 1-t^2. The endpoint |c-a|=b belongs to pair_classification, which proves uniqueness there separately.", "mazhang2026pgmratio"),
            Node("basisFlip", "Exchange the two basis coordinates", DescribeRole.Definition, "The actual linear matrix reindexing M(i,j) -> M(rev i,rev j) exchanges the two orthonormal qubit basis vectors. The proof checks positivity, POVM completeness, actual score invariance and the involution; no scalar symmetry bridge is assumed.", "mazhang2026pgmratio"),
            Node("lowerPovm", "The negative-sign three-active measurement", DescribeRole.Definition, "For t=b/(a-c), the effects are the basis flips of upperPovm(t). Equivalently E_+=[[1,t],[t,t^2]]/2, E_-=[[1,-t],[-t,t^2]]/2 and E_3=diag(0,1-t^2). In the strict lower region b<a-c, all effects are nonzero.", "mazhang2026pgmratio"),
            Node("lower_classification", "Unique optimum in the negative-sign region", DescribeRole.Theorem, "For every a,b,c with 0<b<a-c, the actual lowerPovm(b/(a-c)) is a finitePOVM with success (1+a-c+b^2/(a-c))/3. Every actual complex finitePOVM E is optimal if and only if it equals that measurement. This is derived by an actual basis permutation from the upper classification, transporting all competitors as well as the candidate.", "mazhang2026pgmratio"),
            Node("optimalPovm", "The full piecewise actual optimizer", DescribeRole.Definition, "Use pairPovm when |c-a|<=b, upperPovm(b/(c-a)) when c-a>b, and lowerPovm(b/(a-c)) otherwise. Both equality boundaries are assigned to the unique pair optimum. On the strict density domain 0<a,c<1, 0<b<sqrt(a(1-a)), these are exactly the note’s two-active and three-active effects, in the original label order.", "mazhang2026pgmratio"),
            Node("complete_classification", "Every optimum and its exact active set", DescribeRole.Theorem, "For every b>0 the actual optimalPovm is a finitePOVM, and an arbitrary actual finitePOVM E is optimal among all complex finitePOVMs if and only if E=optimalPovm. Its active set, defined by nonzero effects, is exactly {0,1} when |c-a|<=b and is all three labels otherwise. The physical strict-density theorem is supplied separately by states_posDef; the optimization calculation itself uses no extra positivity assumption on a or c. In the three-active regions the exact success from the two orientation theorems is (1+R)/3 with R=((c-a)^2+b^2)/|c-a|. Both signs and the two equality boundaries are included.", "mazhang2026pgmratio"),
            Node("blochPovm", "Sign-uniform actual three-active effects", DescribeRole.Definition, "For delta=c-a, d0=|delta|, s=delta/d0, R=(delta^2+b^2)/d0 and h=(delta^2-b^2)/delta, the actual effects are E+/-=[(d0^2+b^2)/(2d0^2)](I+/-(2b/R)X-(h/R)Z)/2 and E3=[(d0^2-b^2)/d0^2](I+sZ)/2, using the existing Pauli matrices.", "mazhang2026pgmratio"),
            Node("blochGamma", "Sign-uniform actual dual certificate", DescribeRole.Definition, "With z=2a-1 and the same R,h, Gamma=[(1+R)I+(z+h)Z]/6. The strict three-active theorem proves feasibility of every actual dual slack.", "mazhang2026pgmratio"),
            Node("three_active_formula", "Complete strict-PD three-active equations", DescribeRole.Theorem, "Throughout 0<a,c<1, b>0, b^2<a(1-a), |c-a|>b, all actual states are PD trace-one; optimalPovm equals the displayed blochPovm; it is feasible and uniquely optimal among every complex finitePOVM. Its exact success and dual trace are (1+R)/3, with every actual dual slack PSD. Both signs are proved through actual matrices. The two equality boundaries remain in pair_classification, and the full active failure iff is active_failure_iff. No full classification on non-strict PSD boundaries is asserted.", "mazhang2026pgmratio"),
            Paragraph(Text("Source custody: the mechanism manuscript is anonymous (3 November 2026); no license grant was supplied. The old literal byline remains Wenlin Zhang and Haobo / trureturing, and its actual rational proof is reused as EquiprobablePgmActiveSetRefutation.result. The new note is by Haobo Ma then Wenlin Zhang (4 November 2026), with CC BY 4.0 restricted to that new note. Hyunho Cha is credited for the symmetric scores and qubit/commuting constructions. The metadata URLs locate immutable repository citation records, not public manuscript originals. Activity means a nonzero effect, including rank-one effects; the source wording about positive definite effects is ambiguous. General all-pure and positive-spectral-floor comparisons remain open. No priority or publication claim is made."))
        ), []));
    private static DocumentBlock Node(string name, string title, DescribeRole role, string prose, string? note) => Describe.Lean(
        DescribeId.Create("pgm-symmetric-" + name.Replace('_', '-').ToLowerInvariant()),
        DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
        note is null ? AssessedProvenance.FromRepo() : AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Estimation/" + note)),
        Blocks(Paragraph(Text(prose))), role);
}
